import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.PrintWriter;

/**
 * Oct 3, 2016 | 12:28:10 PM
 * <pre>
 * <u>Description</u>
 *
 * </pre>
 *
 * @author Essiennta Emmanuel (colourfulemmanuel@gmail.com)
 */
public class ProblemB {

    private void process(char[] a, PrintWriter out) {
        int index = 0;
        int maxLength = 0;
        int pairCount = 0;
        boolean inParentheses = false;
        while (index < a.length) {
            if (a[index] == '(') {
                inParentheses = true;
            } else if (a[index] == ')') {
                inParentheses = false;
            } else if (Character.isLetter(a[index]))
                index--;
            if (inParentheses) {
                while (++index != a.length && a[index] != ')' && !Character.isLetter(a[index]));
                if (index == a.length || !Character.isLetter(a[index])) {
                    continue;
                }
                while (Character.isLetter(a[++index]));
                pairCount++;
            } else {
                while (++index != a.length && a[index] != '(' && !Character.isLetter(a[index]));
                if (index == a.length || !Character.isLetter(a[index])) {
                    continue;
                }
                int startIdx = index;
                while (++index != a.length && Character.isLetter(a[index]));
                maxLength = Math.max(maxLength, index - startIdx);
            }
        }
        out.println(maxLength + " " + pairCount);
    }

    public static void main(String[] args) {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter writer = new PrintWriter(System.out)) {
            reader.readLine();
            new ProblemB().process(reader.readLine().toCharArray(), writer);
        }
    }
}
